export function generateAuthSecretInProductionIfDefault<T extends { auth: { secret: string }; env: string }>({
  config,
  defaultAuthSecret = DEFAULT_AUTH_SECRET,
  generateSecret = () => randomBytes(48).toString('hex'),
}: {
  config: T;
  defaultAuthSecret?: string;
  generateSecret?: () => string;
}): { config: T; isGenerated: boolean } {
  if (config.env === 'production' && config.auth.secret === defaultAuthSecret) {
    return { config: { ...config, auth: { ...config.auth, secret: generateSecret() } }, isGenerated: true };
  }

  return { config, isGenerated: false };
}

